/* Lightweight flowing water surfaces and waterfall, shared by both XR eyes. */
AFRAME.registerComponent('living-water',{
 init(){const T=AFRAME.THREE;this.T=T;this.root=new T.Group();this.root.userData.lensSubject='water';this.el.object3D.add(this.root);this.materials=[];this.normalMap=new T.TextureLoader().load('assets/water-normal.jpg');this.normalMap.wrapS=this.normalMap.wrapT=T.RepeatWrapping;this.normalMap.repeat.set(3,3);this.flowMap=new T.TextureLoader().load('assets/waterfall-flow.png');this.flowMap.wrapS=this.flowMap.wrapT=T.RepeatWrapping;this.flowMap.colorSpace=T.SRGBColorSpace;this.material=(fall=false,lake=false)=>{const m=new T.MeshPhysicalMaterial({color:'#ffffff',map:fall?this.flowMap:null,normalMap:this.normalMap,normalScale:new T.Vector2(.4,.4),roughness:fall?.24:.11,metalness:0,clearcoat:1,clearcoatRoughness:.12,transparent:true,opacity:1,side:T.DoubleSide,depthWrite:!fall});if(fall){m.onBeforeCompile=shader=>{shader.fragmentShader=shader.fragmentShader.replace('#include <map_fragment>','#ifdef USE_MAP\nvec4 flowSample=texture2D(map,vMapUv);\ndiffuseColor.a*=flowSample.a;\n#endif')};m.customProgramCacheKey=()=>'white-flow-alpha-v1'}this.materials.push(m);return m};const lakeGeo=new T.PlaneGeometry(2.05,1.44,48,36);lakeGeo.rotateX(-Math.PI/2);const lake=new T.Mesh(lakeGeo,this.material(false,true));lake.position.set(0,.248,.05);this.root.add(lake);this.surfaces=[lake];this.rings=[];for(let i=0;i<3;i++){const ring=new T.Mesh(new T.RingGeometry(.96,1,64),new T.MeshBasicMaterial({color:'#ffffff',transparent:true,opacity:.3,depthWrite:false,side:T.DoubleSide}));ring.rotation.x=-Math.PI/2;ring.position.set(-.18,.268,.04);this.root.add(ring);this.rings.push(ring)}const points=[[-.1,.251,.35],[.15,.246,.7],[.3,.2,1.05],[.17,.14,1.45],[.12,.07,1.9],[.1,.02,2.38]].map(p=>new T.Vector3(...p));const curve=new T.CatmullRomCurve3(points),vertices=[],uvs=[],indices=[];for(let i=0;i<=96;i++){const p=curve.getPoint(i/96),t=curve.getTangent(i/96),side=new T.Vector3(-t.z,0,t.x).normalize();for(let j=0;j<=8;j++){const q=p.clone().addScaledVector(side,(j/8-.5)*.34);vertices.push(q.x,q.y,q.z);uvs.push(j/8,i/96);if(i<96&&j<8){const a=i*9+j;indices.push(a,a+9,a+1,a+1,a+9,a+10)}}}const riverGeo=new T.BufferGeometry();riverGeo.setAttribute('position',new T.Float32BufferAttribute(vertices,3));riverGeo.setAttribute('uv',new T.Float32BufferAttribute(uvs,2));riverGeo.setIndex(indices);riverGeo.computeVertexNormals();const river=new T.Mesh(riverGeo,this.material());this.root.add(river);this.surfaces.push(river);this.surfaces.forEach(mesh=>mesh.userData.basePositions=mesh.geometry.attributes.position.array.slice());const fallGeo=new T.PlaneGeometry(.62,2.1,16,48),waterfall=new T.Mesh(fallGeo,this.material(true));waterfall.position.set(.1,-1.03,2.39);this.root.add(waterfall);const foamCanvas=document.createElement('canvas');foamCanvas.width=foamCanvas.height=64;const ctx=foamCanvas.getContext('2d'),g=ctx.createRadialGradient(32,32,2,32,32,30);g.addColorStop(0,'rgba(255,255,255,.65)');g.addColorStop(.5,'rgba(255,255,255,.22)');g.addColorStop(1,'rgba(255,255,255,0)');ctx.fillStyle=g;ctx.fillRect(0,0,64,64);this.foamTexture=new T.CanvasTexture(foamCanvas);const foam=new T.Mesh(new T.PlaneGeometry(.85,.65),new T.MeshBasicMaterial({map:this.foamTexture,transparent:true,depthWrite:false,side:T.DoubleSide}));foam.rotation.x=-Math.PI/2;foam.position.set(.1,-2.07,2.4);this.root.add(foam);this.foam=foam;this.snowOnly=new T.Group();this.snowOnly.name='snow-over-waterbeds';this.snowOnly.visible=false;this.el.object3D.add(this.snowOnly);const snowMat=new T.MeshStandardMaterial({color:'#ffffff',roughness:1,side:T.DoubleSide});for(const surface of this.surfaces){const cover=new T.Mesh(surface.geometry.clone(),snowMat);cover.position.copy(surface.position);cover.position.y+=.045;this.snowOnly.add(cover)}const drops=new Float32Array(60*3);this.drops=drops;this.dropGeo=new T.BufferGeometry();this.dropGeo.setAttribute('position',new T.BufferAttribute(drops,3));this.root.add(new T.Points(this.dropGeo,new T.PointsMaterial({color:'#ffffff',size:.016,transparent:true,opacity:.5,depthWrite:false,map:this.foamTexture})));},
 tick(time){const snowy=document.getElementById('environment')?.components['tiny-seasons']?.mode==='snowy';this.root.visible=!snowy;this.snowOnly.visible=snowy;if(snowy||document.hidden)return;const t=time/1000;this.normalMap.offset.set(t*.012,t*.019);this.flowMap.offset.y=t*.55;this.rings.forEach((ring,i)=>{const phase=(t*.24+i/3)%1,scale=.1+phase*.58;ring.scale.set(scale,scale*.8,1);ring.material.opacity=Math.sin(phase*Math.PI)*.28});const rain=document.getElementById('environment')?.components['tiny-seasons']?.mode==='rainy'?1:0;this.materials[0].roughness=rain?.26:.16;this.surfaces.forEach(mesh=>{const p=mesh.geometry.attributes.position,base=mesh.userData.basePositions;for(let i=0;i<p.count;i++){const x=base[i*3],z=base[i*3+2],wave=Math.sin(x*18+z*9-t*1.3)*.004+Math.sin(z*27-t*1.9)*(.002+rain*.002);p.setY(i,base[i*3+1]+wave)}p.needsUpdate=true;if(!this.lastNormals||time-this.lastNormals>100)mesh.geometry.computeVertexNormals()});if(!this.lastNormals||time-this.lastNormals>100)this.lastNormals=time;for(let i=0;i<60;i++){const phase=(t*.7+i*.618)%1,a=i*2.399;this.drops[i*3]=.1+Math.cos(a)*phase*.3;this.drops[i*3+1]=-2.07+Math.sin(phase*Math.PI)*.16;this.drops[i*3+2]=2.4+Math.sin(a)*phase*.2}this.dropGeo.attributes.position.needsUpdate=true;this.foam.scale.setScalar(1+Math.sin(t*2)*.035)},
 remove(){this.root.traverse(o=>{o.geometry?.dispose();o.material?.dispose()});this.snowOnly.traverse(o=>{o.geometry?.dispose();o.material?.dispose()});this.snowOnly.removeFromParent();this.foamTexture.dispose();this.normalMap.dispose();this.flowMap.dispose();this.root.removeFromParent()}
});
